export const LANGUAGES=['Deutsch','Polnisch','Russisch'];
export function normalizeAssessment(value){const score=v=>{if(v===''||v===null||v===undefined)return null;const n=Number(v);if(!Number.isInteger(n)||n<1||n>10)throw Error('Bewertungen müssen ganze Zahlen von 1 bis 10 sein.');return n};const experience=value.experience||'';if(!['','gt3','gt5','gt10'].includes(experience))throw Error('Ungültige Erfahrungsstufe.');const text=(s,max)=>String(s||'').trim().slice(0,max);return{quality:score(value.quality),speed:score(value.speed),languages:[...new Set((value.languages||[]).filter(l=>LANGUAGES.includes(l)))],otherLanguages:text(value.otherLanguages,300),communicationNote:text(value.communicationNote,2000),experience,experienceText:text(value.experienceText,2000)};}
export function assessmentScore(worker){if(worker.assessment){const values=[worker.assessment.quality,worker.assessment.speed].filter(n=>Number.isFinite(n)&&n>=1&&n<=10);return values.length?values.reduce((a,b)=>a+b,0)/values.length:null}return typeof worker.rating==='number'&&Number.isFinite(worker.rating)?worker.rating:null;}
